import{_ as r,a0 as l,w as p,s as d,ao as o,I as a,x as t,a1 as n,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Obsidian 中創建和使用鏈接 | LCTT x X-CMD","titleTemplate":false,"description":"在 Obsidian 中創建和使用鏈接 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Obsidian 中創建和使用鏈接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Obsidian 中創建和使用鏈接 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20231211 Creating and Working with Links in Obsidian","title":"在 Obsidian 中創建和使用鏈接","tag":"202401","desc":""},"relativePath":"202401/20231211 Creating and Working with Links in Obsidian.md","filePath":"[post].md"}'),b={name:"202401/20231211 Creating and Working with Links in Obsidian.md"};function g(k,i,u,h,m,f){const s=l("Link");return p(),d("div",null,[i[25]||(i[25]=o('<h1 id="在-obsidian-中創建和使用鏈接" tabindex="-1">在 Obsidian 中創建和使用鏈接 <a class="header-anchor" href="#在-obsidian-中創建和使用鏈接" aria-label="Permalink to “在 Obsidian 中創建和使用鏈接”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/27/095314xdbbtbjek22bbm8r.jpg" alt=""></p><blockquote><p>Obsidian 知識庫工具的真正威力在於鏈接。學習使用它。</p></blockquote><p>Obsidian 的最大賣點之一是其強大的文檔鏈接和可視化。Obsidian 提供了多種鏈接文檔和圖像的方法。我們將逐一介紹。</p><p>你將在 Obsidian 中看到三種內部鏈接方法：</p><ul><li>拖放方式（簡單但有限）</li><li>使用 Markdown 鏈接</li><li>使用維基鏈接（廣泛且強大）</li></ul><p>我還將分享一些有關使用圖表和反向鏈接的技巧。讓我們來看看它。</p><blockquote><p>✋ <strong>非自由和開源軟件警告！</strong> Obsidian 不是開源軟件，我們知道這一事實。然而，它是一種在編碼人員（包括開源開發人員）中非常流行的工具。這就是我們介紹它的原因。</p></blockquote><h3 id="方法-1-通過拖放鏈接" tabindex="-1">方法 1：通過拖放鏈接 <a class="header-anchor" href="#方法-1-通過拖放鏈接" aria-label="Permalink to “方法 1：通過拖放鏈接”">​</a></h3><p>是的，這是最簡單的鏈接。轉到要在其中創建鏈接的文檔。現在，在左側邊欄上，展開該特定文件夾，其中包含目標註釋。</p><p>要創建鏈接，只需將此目標文件拖放到你希望鏈接顯示的位置即可。</p><p><img src="https://itsfoss.com/content/images/2023/12/link-by-drag-and-drop.gif" alt="通過拖放添加鏈接"></p><p>你可以稍後更改鏈接文本。</p><h3 id="方法-2-使用-markdown-鏈接" tabindex="-1">方法 2：使用 Markdown 鏈接 <a class="header-anchor" href="#方法-2-使用-markdown-鏈接" aria-label="Permalink to “方法 2：使用 Markdown 鏈接”">​</a></h3><p>由於 Obsidian 使用 Markdown 作為其核心，因此可以通過輸入傳統的 Markdown 命令進行鏈接。</p><p>比方説，你必須在 “Markdown Advanced” 頁面中創建一個指向 “Markdown Checklist” 頁面的鏈接。首先，你需要記下要鏈接到的文件的位置。</p><p>然後，只需添加這一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[鏈接文本]（文件的相對路徑）</span></span></code></pre></div><p>或者，如果你有要鏈接的文件，並且想要提供系統中的絕對路徑，請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[鏈接文本](file://絕對路徑)</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/12/linking-using-absolute-path.png" alt="使用絕對路徑鏈接"></p>',21)),a("blockquote",null,[a("p",null,[i[1]||(i[1]=t("🚧 如果你 ",-1)),n(s,{href:"https://itsfoss.com/markdown-links/"},{default:e(()=>[...i[0]||(i[0]=[t("使用 Markdown 鏈接",-1)])]),_:1}),i[2]||(i[2]=t("，請確保文件和文件夾的名稱中沒有空格，因為這在某些情況下可能會引起一些麻煩。",-1))])]),i[26]||(i[26]=a("h3",{id:"方法-3-使用緊湊型維基鏈接來鏈接頁面",tabindex:"-1"},[t("方法 3：使用緊湊型維基鏈接來鏈接頁面 "),a("a",{class:"header-anchor",href:"#方法-3-使用緊湊型維基鏈接來鏈接頁面","aria-label":"Permalink to “方法 3：使用緊湊型維基鏈接來鏈接頁面”"},"​")],-1)),a("p",null,[i[5]||(i[5]=t("Obsidian 支持使用 ",-1)),a("ruby",null,[n(s,{href:"https://en.wikipedia.org/wiki/Help:Link"},{default:e(()=>[...i[3]||(i[3]=[t("維基鏈接",-1)])]),_:1}),i[4]||(i[4]=a("rt",null,"Wikilink",-1))]),i[6]||(i[6]=t(" 來鏈接頁面的直觀方式。它們是緊湊的鏈接並且是交互式鏈接。默認情況下，此功能處於打開狀態。",-1))]),i[27]||(i[27]=o('<p>如果你想知道，是的，它與維基百科有關。他們用它來內部鏈接他們的維基頁面。</p><h4 id="添加內部註釋的鏈接" tabindex="-1">添加內部註釋的鏈接 <a class="header-anchor" href="#添加內部註釋的鏈接" aria-label="Permalink to “添加內部註釋的鏈接”">​</a></h4><p>要創建鏈接，只需輸入 <code>[[</code>。這將啓動一個交互式對話框，你可以在其中搜索要鏈接的文檔。</p><p><img src="https://itsfoss.com/content/images/2023/12/add-interactive-wikilinks.gif" alt="添加交互式維基鏈接"></p><blockquote><p>💡 你可以使用 [[link|要顯示的文本]]使自定義文本顯示在維基鏈接上。例如 [[notes/hello.md|這是 Hello 文件的鏈接]]</p></blockquote><h4 id="添加圖像文件" tabindex="-1">添加圖像文件 <a class="header-anchor" href="#添加圖像文件" aria-label="Permalink to “添加圖像文件”">​</a></h4><p>此外，你可以使用此鏈接方法添加其他文件，例如圖像，但在使用 <code>[[</code> 搜索之前需要添加 <code>!</code> 符號。請看下圖以瞭解其實際效果。</p><p><img src="https://itsfoss.com/content/images/2023/12/add-image-using-wikilinks.gif" alt="使用維基鏈接添加圖像"></p><h4 id="添加內部標題鏈接" tabindex="-1">添加內部標題鏈接 <a class="header-anchor" href="#添加內部標題鏈接" aria-label="Permalink to “添加內部標題鏈接”">​</a></h4><p>有一種方法可以在同一頁面的各個標題之間創建內部鏈接。為此，首先輸入 <code>[[</code>，然後使用 Markdown 標題語法和要鏈接的特定標題的名稱。</p><p>例如，如果你打算鏈接到文檔中的第六個標題（2 級標題），請使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[[##Paragraph Six</span></span></code></pre></div><p>這將顯示在交互式選擇中。</p><p><img src="https://itsfoss.com/content/images/2023/12/Link-to-heading-1.gif" alt="鏈接到標題"></p><blockquote><p>💡 你可以將鼠標懸停在鏈接上時按 CTRL 鍵來進行預覽。</p></blockquote><h4 id="添加指向文本塊的鏈接" tabindex="-1">添加指向文本塊的鏈接 <a class="header-anchor" href="#添加指向文本塊的鏈接" aria-label="Permalink to “添加指向文本塊的鏈接”">​</a></h4><p>Obsidian 允許你創建指向文檔中特定文本塊的鏈接。為此，首先，轉到要添加鏈接的塊的最末尾。</p><p>現在，使用 <code>^</code> 符號向該塊添加唯一標識符。</p><p><img src="https://itsfoss.com/content/images/2023/12/Add-unique-identifier-to-a-block.png" alt="向塊添加唯一標識符"></p><p>現在，你可以通過輸入 <code>[[^</code> 來添加到此部分的鏈接。這將自動提示你可用的塊。選擇一項並按回車鍵。</p><p><img src="https://itsfoss.com/content/images/2023/12/your-block-link.gif" alt="添加鏈接到塊"></p><h4 id="維基鏈接的問題" tabindex="-1">維基鏈接的問題 <a class="header-anchor" href="#維基鏈接的問題" aria-label="Permalink to “維基鏈接的問題”">​</a></h4><p>有時，如果你想要純 Markdown 文檔，並且專注於多個 Markdown 編輯器之間的互操作性，那麼維基鏈接功能可能會產生問題。</p><p>由於這些在 Obsidian 內部工作，因此鏈接在其他編輯器上顯示為損壞。在這種情況下，你可以關閉維基鏈接。一切都完美無缺，只是鏈接現在將以 Markdown 格式顯示。</p><p>為此，首先選擇左下角的設置按鈕。</p><p><img src="https://itsfoss.com/content/images/2023/12/click-on-settings-button-in-obsidian.png" alt="點擊設置"></p><p>現在，從 “<ruby>文件和鏈接<rt>Files and Links</rt></ruby>” 選項卡關閉維基鏈接功能。</p><p><img src="https://itsfoss.com/content/images/2023/12/turn-off-the-wikilink-feature.png" alt="關閉維基鏈接功能"></p><h4 id="組織附件文件的提示" tabindex="-1">組織附件文件的提示 <a class="header-anchor" href="#組織附件文件的提示" aria-label="Permalink to “組織附件文件的提示”">​</a></h4><p>對於那些在 Obsidian 中附加許多文件的人，建議在每本書下為這些附件創建一個單獨的文件夾。</p><p>現在，打開 “<ruby>設置<rt>Settings</rt></ruby> &gt; <ruby>文件和鏈接<rt>Files and Links</rt></ruby>”。在這裏，首先，你需要確保鏈接路徑是相對於文件位置的。然後，將新附件的默認位置設置為 “<ruby>當前文件夾下的子文件夾<rt>Subfolder under current folder</rt></ruby>”。現在，在下一個字段中指定 “<ruby>附件<rt>Attachments</rt></ruby>”，即 “<ruby>子文件夾名稱<rt>Subfolder name</rt></ruby>”。</p><p><img src="https://itsfoss.com/content/images/2023/12/set-attachment-folder-location-and-other-settings-1.png" alt="設置附件文件夾位置"></p><p>就是這樣。從現在開始，當你通過複製和粘貼放置任何附件時，它們將自動放置在該筆記文件夾內的“附件”文件夾中。新鏈接將在任何 Markdown 編輯器之間完美地互操作，因為路徑現在是相對於文件位置的。</p><blockquote><p>📋 即使此維基鏈接功能已關閉，你仍然可以使用 [[ 鍵以交互方式搜索和添加鏈接。變化是，現在鏈接不再是緊湊的，而是長 Markdown 鏈接。</p></blockquote><p>此外，你還可以打開 “<ruby>自動更新內部鏈接<rt>Automatically Update Internal Links</rt></ruby>” 按鈕，以確保在重命名文件時自動更新鏈接。</p><h3 id="使用圖表和反向鏈接" tabindex="-1">使用圖表和反向鏈接 <a class="header-anchor" href="#使用圖表和反向鏈接" aria-label="Permalink to “使用圖表和反向鏈接”">​</a></h3><p>創建完鏈接後，就可以通過鏈接查看筆記之間的其他筆記之間的關係。單擊側面的圖表視圖按鈕即可進入圖表預覽。</p><p><img src="https://itsfoss.com/content/images/2023/12/graph-view-in-obsidian.png" alt="Obsidian 中的圖表視圖"></p><p>正如你所看到的，你將在一個整潔的圖表上獲得該註釋的鏈接。如果你按空白選項卡上的圖表視圖，你將獲得所有筆記及其關係。</p><p><img src="https://itsfoss.com/content/images/2023/12/part-of-a-graph-view.png" alt="Notes Vault 示例的一些鏈接示例"></p><p>此外，每個筆記都有一 “傳出鏈接” 和 “傳入鏈接” 選項卡，你可以在其中跟蹤相關鏈接。</p><p><img src="https://itsfoss.com/content/images/2023/12/Links-out-and-in.png" alt="傳出和傳入鏈接"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>正如你所看到的，雖然在 Obsidian 中創建指向其他頁面的內部鏈接很簡單，但通過維基鏈接，你可以創建更加個性化和定製的知識庫。</p>',44)),a("p",null,[i[8]||(i[8]=t("對於那些不喜歡 Obsidian 閉源性質的人來説，",-1)),n(s,{href:"https://itsfoss.com/logseq/"},{default:e(()=>[...i[7]||(i[7]=[t("Logseq",-1)])]),_:1}),i[9]||(i[9]=t(" 是一個不錯的選擇。",-1))]),i[28]||(i[28]=a("p",null,[a("em",null,"（題圖：DA/57173f4d-5548-471f-8d70-a48e3b5e964a）")],-1)),i[29]||(i[29]=a("hr",null,null,-1)),a("p",null,[i[11]||(i[11]=t("via: ",-1)),n(s,{href:"https://itsfoss.com/obsidian-create-links/"},{default:e(()=>[...i[10]||(i[10]=[t("https://itsfoss.com/obsidian-create-links/",-1)])]),_:1})]),a("p",null,[i[16]||(i[16]=t("作者：",-1)),n(s,{href:"https://itsfoss.com/author/sreenath/"},{default:e(()=>[...i[12]||(i[12]=[t("Sreenath",-1)])]),_:1}),i[17]||(i[17]=t(" 選題：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[13]||(i[13]=[t("lujun9972",-1)])]),_:1}),i[18]||(i[18]=t(" 譯者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:e(()=>[...i[14]||(i[14]=[t("geekpi",-1)])]),_:1}),i[19]||(i[19]=t(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:e(()=>[...i[15]||(i[15]=[t("wxy",-1)])]),_:1})]),a("p",null,[i[22]||(i[22]=t("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[20]||(i[20]=[t("LCTT",-1)])]),_:1}),i[23]||(i[23]=t(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:e(()=>[...i[21]||(i[21]=[t("Linux中國",-1)])]),_:1}),i[24]||(i[24]=t(" 榮譽推出",-1))])])}const C=r(b,[["render",g]]);export{x as __pageData,C as default};
